from ortools.linear_solver import pywraplp
import json

def solve_cutting_problem():
    table_length = 25
    table_width = 18

    categories = [1, 2, 3, 4, 5]

    length = {1: 7, 2: 6, 3: 5, 4: 8, 5: 4}
    width = {1: 5, 2: 4, 3: 5, 4: 3, 5: 6}
    value = {1: 35, 2: 24, 3: 25, 4: 24, 5: 24}
    max_qty = {1: 3, 2: 3, 3: 3, 4: 3, 5: 3}

    solver = pywraplp.Solver.CreateSolver("SCIP")
    INF = solver.infinity()

    use = {}
    x = {}
    y = {}
    rot = {}

    for c in categories:
        use[c] = {}
        x[c] = {}
        y[c] = {}
        rot[c] = {}
        for k in range(1, max_qty[c] + 1):
            use[c][k] = solver.BoolVar(f"use_{c}_{k}")
            x[c][k] = solver.NumVar(0, table_length, f"x_{c}_{k}")
            y[c][k] = solver.NumVar(0, table_width, f"y_{c}_{k}")
            rot[c][k] = solver.BoolVar(f"rot_{c}_{k}")

    pieces = []
    for c in categories:
        for k in range(1, max_qty[c] + 1):
            pieces.append((c, k))

    sep_left = {}
    sep_right = {}
    sep_below = {}
    sep_above = {}

    for i in range(len(pieces)):
        c1, k1 = pieces[i]
        for j in range(i + 1, len(pieces)):
            c2, k2 = pieces[j]
            sep_left[(c1, k1, c2, k2)] = solver.BoolVar(f"sep_left_{c1}_{k1}_{c2}_{k2}")
            sep_right[(c1, k1, c2, k2)] = solver.BoolVar(f"sep_right_{c1}_{k1}_{c2}_{k2}")
            sep_below[(c1, k1, c2, k2)] = solver.BoolVar(f"sep_below_{c1}_{k1}_{c2}_{k2}")
            sep_above[(c1, k1, c2, k2)] = solver.BoolVar(f"sep_above_{c1}_{k1}_{c2}_{k2}")

    for c in categories:
        for k in range(1, max_qty[c] + 1):
            solver.Add(
                x[c][k] + (1 - rot[c][k]) * length[c] + rot[c][k] * width[c] 
                <= table_length + table_length * (1 - use[c][k])
            )

            solver.Add(
                y[c][k] + (1 - rot[c][k]) * width[c] + rot[c][k] * length[c]
                <= table_width + table_width * (1 - use[c][k])
            )

            solver.Add(x[c][k] <= table_length * use[c][k])

            solver.Add(y[c][k] <= table_width * use[c][k])

    for i in range(len(pieces)):
        c1, k1 = pieces[i]
        for j in range(i + 1, len(pieces)):
            c2, k2 = pieces[j]

            solver.Add(
                sep_left[(c1, k1, c2, k2)] + sep_right[(c1, k1, c2, k2)] + 
                sep_below[(c1, k1, c2, k2)] + sep_above[(c1, k1, c2, k2)]
                >= use[c1][k1] + use[c2][k2] - 1
            )

            solver.Add(
                x[c1][k1] + (1 - rot[c1][k1]) * length[c1] + rot[c1][k1] * width[c1]
                <= x[c2][k2] + table_length * (1 - sep_left[(c1, k1, c2, k2)])
            )

            solver.Add(
                x[c2][k2] + (1 - rot[c2][k2]) * length[c2] + rot[c2][k2] * width[c2]
                <= x[c1][k1] + table_length * (1 - sep_right[(c1, k1, c2, k2)])
            )

            solver.Add(
                y[c1][k1] + (1 - rot[c1][k1]) * width[c1] + rot[c1][k1] * length[c1]
                <= y[c2][k2] + table_width * (1 - sep_below[(c1, k1, c2, k2)])
            )

            solver.Add(
                y[c2][k2] + (1 - rot[c2][k2]) * width[c2] + rot[c2][k2] * length[c2]
                <= y[c1][k1] + table_width * (1 - sep_above[(c1, k1, c2, k2)])
            )

    objective = solver.Objective()
    for c in categories:
        for k in range(1, max_qty[c] + 1):
            objective.SetCoefficient(use[c][k], value[c])
    objective.SetMaximization()

    solver.set_time_limit(30000)
    status = solver.Solve()

    if status == pywraplp.Solver.OPTIMAL or status == pywraplp.Solver.FEASIBLE:
        placements = []
        total_value = 0

        for c in categories:
            for k in range(1, max_qty[c] + 1):
                if use[c][k].solution_value() > 0.5:
                    x_val = x[c][k].solution_value()
                    y_val = y[c][k].solution_value()
                    rot_val = int(rot[c][k].solution_value() > 0.5)

                    placements.append([c - 1, int(round(x_val)), int(round(y_val)), rot_val])
                    total_value += value[c]

        print(json.dumps({"placements": placements, "total_value": total_value}))
    else:
        print(json.dumps({"placements": [], "total_value": 0}))

if __name__ == "__main__":
    solve_cutting_problem()
